<template>
  <div class="ed-shell">
    <!-- 顶部工具栏 -->
    <header class="ed-toolbar">
      <div class="ed-brand">
        <span class="ed-logo"></span>
        <span>集装箱住宅编辑器</span>
      </div>

      <!-- 视角按钮组 -->
      <div class="ed-view-group">
        <button class="tb-btn" @click="view('front')">正面</button>
        <button class="tb-btn" @click="view('left')">侧面 A</button>
        <button class="tb-btn" @click="view('right')">侧面 B</button>
        <button class="tb-btn" @click="view('top')">俯视</button>
        <button class="tb-btn primary" @click="view('front')">重置视角</button>
      </div>
      <div class="ed-view-group">
        <label class="tb-switch">
          <input type="checkbox" :checked="viewerRef ? viewerRef.autoRotate : false" @change="toggleRotate">
          <span>自动旋转</span>
        </label>
        <label class="tb-switch">
          <input type="checkbox" :checked="viewerRef ? viewerRef.showDims : false" @change="toggleDims">
          <span>尺寸标注</span>
        </label>
      </div>

      <div class="ed-spacer"></div>

      <!-- 主模型切换（切换会重置当前编辑状态并重新加载模型）。桌面/平板：顶栏右端横排分段；
           仅一个可见模型时整组隐藏，直接展示该模型 -->
      <div v-if="models.length > 1" class="ed-model-switch ed-model-switch--top" title="切换主模型（当前编辑状态将重置）">
        <button v-for="m in models" :key="m.key" class="ms-btn" :class="{ on: m.key === modelKey }"
          @click="switchModel(m.key)">{{ m.label }}</button>
      </div>
    </header>

    <!-- 室内分割方案 tab：悬浮于顶栏下方（仅屋顶打开时显示，多版本热切换无需重载） -->
    <div v-if="partitionVersions.length > 1 && roofOpen" class="ed-ptab-bar" title="切换室内分割方案">
      <button v-for="pv in partitionVersions" :key="pv.key" class="ptab-btn"
        :class="{ on: pv.key === partitionVersion }" @click="switchPartition(pv.key)">{{ pv.name }}</button>
    </div>

    <!-- 移动端：主模型切换移到顶部导航栏正下方、竖排两行（桌面隐藏；切换会重置编辑状态） -->
    <div v-if="models.length > 1" class="ed-model-switch ed-model-switch--mobile" title="切换主模型（当前编辑状态将重置）">
      <button v-for="m in models" :key="m.key" class="ms-btn" :class="{ on: m.key === modelKey }"
        @click="switchModel(m.key)">{{ m.label }}</button>
    </div>

    <!-- 切换主模型：以 :key 整体重挂载 3D 视口 + 右侧面板（各自在 setup 读取新模型上下文） -->
    <div :key="modelKey" class="ed-main">
      <!-- 中间：3D 视口 -->
      <Viewer3D ref="viewerRef" class="ed-viewport" />

      <!-- 右侧：整体设置 / 部件库 / 属性 -->
      <RightPanel :catalog="catalog" />
    </div>
  </div>
</template>

<script>
import { ref, computed } from 'vue'
import RightPanel from '../components/editor/RightPanel.vue'
import Viewer3D from '../components/editor/Viewer3D.vue'
import { MODEL_KEYS, resolvePartitionPlan } from '../lib/catalog'
import { modelCtx, setModel, getCtx } from '../lib/modelCtx'
import { resetForModel, editorState } from '../lib/editorState'

/** 模型切换列表（顺序 = MODEL_KEYS 注册顺序；仅一个可见模型时切换组自动隐藏） */
const MODEL_LABELS = { '22': '集装箱 22' }

export default {
  name: 'EditorPage',
  components: { RightPanel, Viewer3D },
  setup() {
    const viewerRef = ref(null)
    const modelKey = computed(() => modelCtx.key)
    const catalog = computed(() => getCtx().catalog)
    const models = MODEL_KEYS.map((k) => ({ key: k, label: MODEL_LABELS[k] || ('模型 ' + k) }))

    // 启动即按默认模型初始化整体尺寸等编辑状态
    resetForModel(getCtx())

    /** 顶栏视角按钮 → 调用 3D 视口方法 */
    function view(name) {
      if (viewerRef.value) viewerRef.value.setView(name)
    }
    function toggleRotate() {
      if (viewerRef.value) viewerRef.value.toggleAutoRotate()
    }
    function toggleDims() {
      if (viewerRef.value) viewerRef.value.toggleDims()
    }

    /** 室内分割方案 tab（模型 22 多版本）：列表取「当前整体尺寸规格」对应的户型（各规格独立户型，
     *  2026-09-11）——20/30/40 尺各自一套 versions，切换走 Viewer3D 热切换 */
    const partitionVersions = computed(() => {
      const c = getCtx()
      const axisLen = (c.meta && c.meta.axis && c.meta.axis.length) || 'z'
      const plan = resolvePartitionPlan(c.meta, +editorState.sizes.model[axisLen] || 0)
      if (!plan || !plan.versions) return []
      return Object.keys(plan.versions).map((k) => ({ key: k, name: plan.versions[k].name || ('方案 ' + k) }))
    })
    const partitionVersion = computed(() => (viewerRef.value ? viewerRef.value.partitionVersion : ''))
    /** 屋顶打开（=屋顶隐藏俯瞰）时才显示分割 tab（与 3D 内开屋顶动作联动，keyVisible.roof===false） */
    const roofOpen = computed(() => editorState.keyVisible.roof === false)
    function switchPartition(key) {
      if (viewerRef.value) viewerRef.value.switchPartition(key)
    }

    /** 切换主模型：设置上下文 → 重置编辑状态 → :key 重挂载 3D 视口与面板 */
    function switchModel(key) {
      if (String(key) === String(modelCtx.key)) return
      setModel(key)
      resetForModel(getCtx())
    }

    return { modelKey, models, catalog, viewerRef, view, toggleRotate, toggleDims, switchModel, partitionVersions, partitionVersion, switchPartition, roofOpen }
  }
}
</script>

