        <label><span>宽（W）</span><input ref="widRef" disabled type="number" step="0.001" min="0.001"
            v-model.number="draft[axis.width]" @change="applyModel"></label>
        <label><span>高（H）</span><input ref="heiRef" disabled type="number" step="0.001" min="0.001"
