<script>
import { ref, computed, watch, nextTick } from 'vue'
import { getCtx } from '../../lib/modelCtx'
import { SCALE } from '../../lib/catalog'
import { editorState, requestSizeEdit, requestTextureApply } from '../../lib/editorState'

export default {
  name: 'PanelOverall',
  props: {
    info: { type: Object, required: true }
  },
  setup(props) {
    const ctx = getCtx()
    // 尺寸轴映射：缺省 长 Z / 宽 X；22 在 catalog meta.axis 声明为 长 X / 宽 Z。
    const axis = (ctx.meta && ctx.meta.axis) || { length: 'z', width: 'x', height: 'y' }
    const sections = ctx.catalog.sections
    const showGrid = ref(editorState.display.grid)
    const light = editorState.lighting // 直接改响应式状态，Viewer3D watch 应用

    const LIGHT_DEFAULT = { hemi: 0.55, key: 1.7, fill: 0.4, dirX: 6, dirY: 9, dirZ: 5, background: '#e9f0f8' }
    function resetLight() {
      Object.assign(light, LIGHT_DEFAULT)
    }

    // 模型尺寸草稿（整体尺寸变化后同步）
    const draft = ref({ ...editorState.sizes.model })
    watch(
      () => ({ ...editorState.sizes.model }),
      (v) => { draft.value = { ...v } },
      { deep: true }
    )

    /* ===== 集装箱规格预设（20 / 30 / 40 尺）=====
     * 目标长度来自 catalog meta.sizePresets（显式米值，用户 2026-09-11 给定）：
     * 20 尺 → 5.9m / 30 尺 → 9.0m / 40 尺 = 模型原长 11.8m。
     * 未声明时按「基准规格（meta.sizeBaseFt，缺省 20 尺）等比长度」兜底。
     * 只改长度轴 —— 宽 / 高是箱体断面尺寸，不随规格变化；用户手动调过的宽 / 高不会被覆盖。 */
    const BASE_FT = +(ctx.meta && ctx.meta.sizeBaseFt) || 20
    // 基准外部尺寸（米）：origInMeters 的模型直接用，否则按 SCALE 换算（与 resetForModel 同口径）
    const _s = ctx.meta && ctx.meta.origInMeters ? 1 : SCALE
    const BASE_SIZE = {
      x: +((ctx.MODEL_ORIG.x || 0) * _s).toFixed(3),
      y: +((ctx.MODEL_ORIG.y || 0) * _s).toFixed(3),
      z: +((ctx.MODEL_ORIG.z || 0) * _s).toFixed(3)
    }
    const _declared = ctx.meta && Array.isArray(ctx.meta.sizePresets) ? ctx.meta.sizePresets : null
    const sizePresets = _declared
      ? _declared.map((p) => ({ ft: p.ft, label: p.label || `${p.ft} 尺`, len: +p.len }))
      : [20, 30, 40].map((ft) => ({
        ft, label: `${ft} 尺`, len: +(BASE_SIZE[axis.length] * (ft / BASE_FT)).toFixed(3)
      }))
    /** 当前长度是否即该规格（±5cm 容差 → 按钮高亮） */
    function isPresetOn(p) {
      const cur = +draft.value[axis.length] || 0
      return Math.abs(cur - p.len) < 0.05
    }
    /** 模型名称随尺码联动（2026-09-17 用户「怎么一直显示的是40尺双翼拓展箱」）：
     * info.label 是 MODEL_DEFS 注册时的静态名（按 40 尺原长口径写的）。当前长度命中
     * 某个尺码预设（±5cm，与 isPresetOn 同口径）时，把名称里开头的「N尺」前缀换成
     * 当前尺码（40尺双翼拓展箱 → 20尺双翼拓展箱）；自由尺寸（不命中任何预设）回落注册名。 */
    const displayLabel = computed(() => {
      const base = props.info && props.info.label
      if (!base) return base
      const hit = sizePresets.find((p) => isPresetOn(p))
      if (!hit) return base
      return base.replace(/^[0-9.]+\s*尺/, `${hit.ft}尺`)
    })
    /** 套用规格：仅改长度轴，宽 / 高保持当前值 */
    function applyPreset(p) {
      const d = { ...draft.value, [axis.length]: +p.len }
      draft.value = d
      requestSizeEdit('model', { x: d.x, y: d.y, z: d.z })
    }

    function isGroupOn(id) {
      // 屋顶与 3D「开屋顶」共用 keyVisible.roof（两套状态已统一，2026-09-11）：
      // 任意一处置为隐藏都视为关闭，眼睛状态才与实际一致。
      if (id === 'roof') {
        return editorState.display.groups[id] !== false && editorState.keyVisible.roof !== false
      }
      return editorState.display.groups[id] !== false
    }
    /** 内部净尺寸展示：按模型轴映射 长×宽×高（米） */
    function fmtInner(o) {
      if (!o) return ''
      const L = o[axis.length]
      const W = o[axis.width]
      const H = o[axis.height]
      return `长 ${L} m × 宽 ${W} m × 高 ${H} m`
    }
    /* 内部净尺寸 / 占地面积随整体尺寸联动（2026-09-11）：
     * catalog 声明的 外部净尺寸 − 内部净尺寸 = 固定差值（产品规格口径：两侧墙 170、顶底 120、侧墙 110），
     * 该差值不随 3D 等比缩放变化 → 当前内净 = 当前整体尺寸 − 差值。
     * 对应关系（用户 2026-09-11 给定）：20 尺内净长 5.56m / 30 尺 8.66m / 40 尺 11.46m。 */
    const SIZE_GAP = (() => {
      const inner0 = ctx.meta && ctx.meta.inner
      if (!inner0) return null
      const s = ctx.meta.origInMeters ? 1 : SCALE
      return {
        x: ctx.MODEL_ORIG.x * s - inner0.x,
        y: ctx.MODEL_ORIG.y * s - inner0.y,
        z: ctx.MODEL_ORIG.z * s - inner0.z
      }
    })()
    /** 当前内部净尺寸（米，随尺寸框实时变化） */
    const innerSize = computed(() => {
      if (!SIZE_GAP) return null
      const d = draft.value
      const r2 = (v) => +v.toFixed(2)
      return { x: r2(d.x - SIZE_GAP.x), y: r2(d.y - SIZE_GAP.y), z: r2(d.z - SIZE_GAP.z) }
    })
    /** 当前占地面积（m²）= 长 × 宽（按模型轴映射） */
    const curArea = computed(() => {
      const l = +draft.value[axis.length] || 0
      const w = +draft.value[axis.width] || 0
      return +(l * w).toFixed(2)
    })
    function toggleGroup(id, on) {
      editorState.display.groups[id] = on
      // 屋顶联动（2026-09-11 用户要求：整体设置的显隐屋顶也要控制分割方案显隐）：
      // 同步写 keyVisible.roof（3D 开屋顶同一状态）→ EditorPage.roofOpen 生效，
      // 顶栏分割方案 tab 出现/消失，与 3D 内开屋顶行为完全一致（不自动切俯视相机）。
      if (id === 'roof') editorState.keyVisible.roof = on
    }
    function setGrid(on) {
      editorState.display.grid = on
      showGrid.value = on
    }
    /** 一键恢复所有墙体原始贴图（all=true + texId='original'） */
    function restoreWallTextures() {
      requestTextureApply('', 'original', 1, true)
    }
    function applyModel() {
      const d = draft.value
      requestSizeEdit('model', { x: d.x, y: d.y, z: d.z })
    }

    // 尺寸标注点击 → 聚焦对应输入框（长/宽/高）
    const lenRef = ref(null)
    const widRef = ref(null)
    const heiRef = ref(null)
    const FIELD_REFS = { length: lenRef, width: widRef, height: heiRef }
    watch(
      () => editorState.focusField,
      (f) => {
        if (!f) return
        // 等 PanelOverall 完成挂载/渲染后再聚焦输入框
        nextTick(() => {
          const r = FIELD_REFS[f]
          if (r && r.value) {
            r.value.focus()
            r.value.select()
          }
        })
        // 清除，避免重复聚焦
        editorState.focusField = ''
      }
    )

    return { sections, axis, showGrid, draft, light, resetLight, isGroupOn, fmtInner, innerSize, curArea, toggleGroup, setGrid, applyModel, lenRef, widRef, heiRef, restoreWallTextures, sizePresets, isPresetOn, applyPreset, displayLabel }
  }
}
</script>

