const toM = (v) => Math.round(v * SCALE * 1000) / 1000
const fmtSize = (s) => s.map(toM)
const fmtPos = (c) => c.map(toM)
const pad = (n) => String(n).padStart(2, '0')

/** 部件条目 */
function partEntry(p, sub, opts = {}) {
  return {
    id: opts.id || p.name,
    name: opts.name || p.name,
    mesh: p.name,
    sub: sub || '',
    material: p.material,
    size: fmtSize(p.size),
    sizeRaw: p.size,
    center: fmtPos(p.center)
  }
}

/** 按坐标排序：axisSeq 为比较轴顺序（原始单位中心坐标，先比较的轴优先） */
function sortByAxes(parts, axisSeq) {
  return [...parts].sort((a, b) => {
    for (const ax of axisSeq) {
      if (a.center[ax] !== b.center[ax]) return a.center[ax] - b.center[ax]
    }
    return 0
  })
}

/** 一组原始单位 parts 的并集包围盒（墙面合并用：整面墙的尺寸/中心取各板并集）。
 *  k = [kx,ky,kz] 原始单位 → 米的换算系数；缺省 SCALE（常规模型口径）。
 *  合并墙面传真实米系数，使面板显示的尺寸/中心与 3D 实测一致。 */
function unionRawBox(parts, k = [SCALE, SCALE, SCALE]) {
  const min = [Infinity, Infinity, Infinity]
  const max = [-Infinity, -Infinity, -Infinity]
  parts.forEach((p) => {
    for (let i = 0; i < 3; i++) {
      min[i] = Math.min(min[i], p.center[i] - p.size[i] / 2)
      max[i] = Math.max(max[i], p.center[i] + p.size[i] / 2)
    }
  })
  const rnd = (v) => Math.round(v * 1000) / 1000
  const sizeRaw = max.map((v, i) => v - min[i])
  return {
    center: min.map((v, i) => rnd(((v + max[i]) / 2) * k[i])),
    size: sizeRaw.map((v, i) => rnd(v * k[i])),
    sizeRaw
  }
}

/** 组合体条目（窗 / 门等 items 各自成条） */
function comboItem(item, group) {
  return {
    id: item.id,
    name: item.name,
    group: group.name,
    type: group.type,
    kind: 'combo',
    role: item.role || '',
    wall: item.wall || '',
    parts: item.parts.map((p) => partEntry(p)),
    box: item.box ? { min: item.box.min.map(toM), max: item.box.max.map(toM), size: item.box.size.map(toM) } : null,
    count: item.parts.length
  }
}

/** 单部件组合体（屋顶 / 地板：直接持有 parts[]，schema 见分类文件）
 *  id 采用分组键（roof/floor，与旧版 keyVisible['roof'] 等语义一致）；name 为中文显示名。 */
function comboFlat(group, name, role) {
  const parts = (group && Array.isArray(group.parts) ? group.parts : []).map((p) => partEntry(p))
  const box = group && group.box
    ? { min: group.box.min.map(toM), max: group.box.max.map(toM), size: group.box.size.map(toM) }
    : null
  const gid = (group && group.id) || name
  return {
    id: gid, name, group: gid, type: group ? group.type : gid, kind: 'combo', role,
    parts, count: parts.length, box
  }
}

/** 构建一份分类原始对象 → 前端 catalog */
export function createCatalog(raw, meta = {}) {
  // 原始单位 → 米 的真实换算系数。
  // 常规模型 = SCALE（0.03）；22 声明 origInMeters → 按 meta.orig / GLB 原始全局尺寸
  // 逐轴换算（与 Viewer3D.loadModel 的 fitScale 同源），使面板展示值与 3D 实测一致。
  const rawOrigin = (raw.meta && raw.meta.orig) || null
  const KM = (meta.origInMeters && rawOrigin && rawOrigin.x && rawOrigin.y && rawOrigin.z)
    ? [meta.orig.x / rawOrigin.x, meta.orig.y / rawOrigin.y, meta.orig.z / rawOrigin.z]
    : [SCALE, SCALE, SCALE]

  const groups = {}
    ; (raw.groups || []).forEach((g) => { groups[g.id] = g })
  const get = (id) => groups[id] || { id, items: [], parts: [], box: null }
  const doorG = get('door')
  const windowG = get('window')
  const roofG = get('roof')
  const floorG = get('floor')
  const wallG = get('wall')
  const frameG = get('frame')

  /** 墙体：各 wall 面 → 编号墙体NN（面内从左到右编号）。
   *  meta.mergeWalls 列出的 wall group 改为「整面墙 = 1 个部件条目」：
   *  id 直接用 group id（如 wall_zn），meshes 存全部成员 mesh 名（Viewer3D 据此把多块板
   *  映射到同一选中键 → 一起高亮/显隐/聚焦/贴图），children 保留单板原始编号信息。
   *  其余 group 仍按「一块板 = 一个编号部件」拆分（编号跨组全局连续）。 */
  function buildWallGroups() {
    const mergeMap = meta.mergeWalls || {}
    let seq = 0
    return (wallG.items || []).map((it) => {
      const axis = it.id.indexOf('_xn') >= 0 || it.id.indexOf('_xp') >= 0 ? 2 : 0
      const sorted = sortByAxes(it.parts || [], [axis])
      const mergeName = mergeMap[it.id]
      if (mergeName) {
        const children = sorted.map((p) => partEntry(p, it.name))
        const box = unionRawBox(sorted, KM)
        const mats = children.map((c) => c.material).filter((v, i, a) => a.indexOf(v) === i)
        const entry = {
          id: it.id,
          name: typeof mergeName === 'string' ? mergeName : it.name,
          sub: it.name,
          mesh: children.map((c) => c.mesh).join(' + '),
          meshes: children.map((c) => c.mesh),
          material: mats.join(' + '),
          size: box.size,
          sizeRaw: box.sizeRaw,
          center: box.center,
          children,
          merged: true
        }
        return {
          id: it.id, name: it.name, group: '墙体', type: it.type,
          kind: 'part-group', parts: [entry], count: 1, merged: true
        }
      }
      const parts = sorted.map((p) => {
        seq++
        return partEntry(p, it.name, { id: `wall_${pad(seq)}`, name: `墙体${pad(seq)}` })
      })
      return {
        id: it.id, name: it.name, group: '墙体', type: it.type,
        kind: 'part-group', parts, count: parts.length
      }
    })
  }

  /** 框架：各 frame 类 → 类名01~ 编号（组内按 z→x→y 排序） */
  function buildFrameGroups() {
    return (frameG.items || []).map((it) => {
      const sorted = sortByAxes(it.parts || [], [2, 0, 1])
      const parts = sorted.map((p, i) => {
        const n = i + 1
        return partEntry(p, it.name, { id: `${it.id}_${pad(n)}`, name: `${it.name}${pad(n)}` })
      })
      return {
        id: it.id, name: it.name, group: '框架', type: it.type,
        kind: 'part-group', parts, count: parts.length
      }
    })
  }

  const doorSeparate = meta.doors === 'separate'

  // 门 section：doors==='merge' 时合并成 1 个 combo（door1/door2 变 subs）；'separate'（22）→ 各自成 item
  let doorItem
  const doorItems = (doorG.items || []).map((it) => comboItem(it, doorG))
  if (doorSeparate) {
    doorItem = null
  } else {
    const doorSubs = doorItems.map((it) => ({
      id: it.id, name: it.name, parts: it.parts, count: it.count
    }))
    doorItem = {
      id: 'door',
      name: '门',
      group: '门',
      type: 'door',
      kind: 'combo',
      role: '整门（两扇）',
      subs: doorSubs,
      parts: doorItems.flatMap((it) => it.parts),
      count: doorItems.reduce((n, it) => n + it.count, 0),
      box: null
    }
  }

  const roof = comboFlat(roofG, '屋顶', '屋顶组件')
  const floor = comboFlat(floorG, '地板', '地板组件')
  // 窗户清除（meta.removeWindows，模型 22）：被移除的整窗不进部件库列表与计数，
  // 改由 catalog.removedWindows 交给 Viewer3D 做「整窗摘除 + 洞口补板」。
  const removeWinKeys = new Set((meta.removeWindows || []).map((r) => r.key))
  const allWinItems = (windowG.items || []).map((it) => comboItem(it, windowG))
  const removedWindows = allWinItems.filter((it) => removeWinKeys.has(it.id))
  const winItems = allWinItems.filter((it) => !removeWinKeys.has(it.id))
  // 先构建组，count 取「部件条目数」——墙面合并后条目数 ≠ 原始 mesh 数（2026-09-14）
  const wallGroups = buildWallGroups()
  const frameGroups = buildFrameGroups()

  const sections = [
    {
      id: 'window', name: '窗户', unit: '扇', color: '#38bdf8',
      type: 'combo-list', count: winItems.length,
      items: winItems
    },
    {
      id: 'door', name: '门', unit: '扇', color: '#f59e0b',
      type: 'combo-list',
      count: doorSeparate ? doorItems.length : 1,
      items: doorSeparate ? doorItems : [doorItem]
    },
    {
      id: 'roof', name: '屋顶', unit: '个', color: '#ef4444',
      type: 'combo-list', count: roof.count ? 1 : 0,
      items: roof.count ? [roof] : []
    },
    {
      id: 'floor', name: '地板', unit: '个', color: '#8b98a5',
      type: 'combo-list', count: floor.count ? 1 : 0,
      items: floor.count ? [floor] : []
    },
    {
      id: 'wall', name: '墙体', unit: '个', color: '#64748b',
      type: 'flat-groups', count: wallGroups.reduce((n, g) => n + g.parts.length, 0),
      groups: wallGroups
    },
    {
      id: 'frame', name: '框架', unit: '个', color: '#334155',
      type: 'flat-groups', count: frameGroups.reduce((n, g) => n + g.parts.length, 0),
      groups: frameGroups
    }
  ]

  const MODEL_ORIG = meta.orig || { x: 48.565, y: 24.8, z: 59.0 }
  const inner = meta.inner || null
  const area = +(MODEL_ORIG.x * MODEL_ORIG.z).toFixed(2)
  return {
    sections,
    door: doorItem || { id: 'door', name: '门', parts: doorItems.flatMap((i) => i.parts), count: doorItems.reduce((n, i) => n + i.count, 0), subs: doorItems.map((i) => ({ id: i.id, name: i.name, parts: i.parts, count: i.count })) },
    roof,
    floor,
    removedWindows, // meta.removeWindows 命中的整窗条目（供 Viewer3D 摘除 + 补板）
    MODEL_ORIG,
    MODEL_INFO: {
      file: raw.model,
      totalParts: raw.totalParts || 0,
      unit: meta.origInMeters ? '米' : (raw.unit || '原始单位（1 = 10cm，展示为米）'),
      orig: MODEL_ORIG,
      inner,
      area,
      specs: meta.specs || [],
      origInMeters: !!meta.origInMeters
    },
    meta
  }
}

/** 构建一个模型上下文（含 catalog / 常量 / 文件信息） */
export function buildModelContext(key) {
  const def = MODEL_DEFS[key]
  if (!def) throw new Error('未知模型: ' + key)
  const meta = { ...(def.raw.meta || {}), ...def.meta }
  const catalog = createCatalog(def.raw, meta)
  const MODEL_INFO = { ...catalog.MODEL_INFO, key: def.key, label: def.label, tip: def.tip || '' }
  return {
    key,
    label: def.label,
    tip: def.tip || '',
    file: def.file,
    url: def.url,
    catalog,
    meta,
    MODEL_ORIG: catalog.MODEL_ORIG,
    MODEL_INFO
  }
}

/**
 * 解析当前整体尺寸下生效的室内分割方案（各规格独立户型，2026-09-11）。
 * @param {object} meta 模型 meta（interiorPartitions / sizePresets / sizeBaseFt）
 * @param {number} curLen 当前整体长度（米，沿 meta.axis.length 轴）
 * @returns {{cfg,ft,declared,planLen,wallH,leafH,version,versions,walls,doors}|null}
 *   declared=true  → 户型数据已按该规格设计（bySize 命中 or 基准规格），毫米图原样铺、内净富余时居中；
 *   declared=false → 回退基准户型，调用方须按 innerLen/planLen 等比压缩长度轴（防穿墙）；
 *   **null**       → 该尺码没有对应户型（未在 bySize 登记），调用方不应生成任何分割。
 */
export function resolvePartitionPlan(meta, curLen) {
  const cfg = meta && meta.interiorPartitions
  if (!cfg || !cfg.enabled) return null
  const baseFt = +meta.sizeBaseFt || 40
  // 尺码命中：与 sizePresets 的 len 比对，±5cm 内取最近的一个
  let ft = null
  let best = Infinity
    ; (meta.sizePresets || []).forEach((p) => {
      const d = Math.abs((curLen || 0) - p.len)
      if (d < 0.05 && d < best) { best = d; ft = p.ft }
    })
  const sv = (ft != null && cfg.bySize && cfg.bySize[ft]) || null
  const isBase = ft === baseFt
  // 标准尺码但没登记户型（如 20 / 30 尺暂无户型图，2026-09-11 用户确认）→ 不生成分割。
  // 非标准尺码（自由尺寸，ft=null）仍按基准户型等比兜底 —— 避免手改尺寸时分割凭空消失。
  if (!sv && ft != null && !isBase) return null
  const src = sv || cfg
  return {
    cfg,
    ft,
    declared: !!sv || isBase,
    planLen: src.planLen || cfg.planLen || 11300,
    wallH: src.wallH || cfg.wallH || 2.24,
    leafH: src.leafH || cfg.leafH || 2.0,
    version: src.version || '',
    versions: src.versions || null,
    walls: src.walls || null,
    doors: src.doors || null
  }
}

export const DEFAULT_MODEL = '22'
/** UI 可见模型 key 列表（顺序 = MODEL_DEFS 注册顺序；hidden 的模型不对外暴露） */
export const MODEL_KEYS = Object.keys(MODEL_DEFS).filter((k) => !MODEL_DEFS[k].hidden)
