const cache = new Map()

function canvasTexture(draw, size = 512) {
  const cv = document.createElement('canvas')
  cv.width = cv.height = size
  draw(cv.getContext('2d'), size)
  const tex = new THREE.CanvasTexture(cv)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

// 给 RGBA 字符串加上噪点（让材质有真实感）
function addNoise(ctx, s, alpha = 10) {
  const img = ctx.getImageData(0, 0, s, s)
  const d = img.data
  for (let i = 0; i < d.length; i += 4) {
    const n = (Math.random() - 0.5) * alpha * 2
    d[i] = Math.min(255, Math.max(0, d[i] + n))
    d[i + 1] = Math.min(255, Math.max(0, d[i + 1] + n))
    d[i + 2] = Math.min(255, Math.max(0, d[i + 2] + n))
  }
  ctx.putImageData(img, 0, 0)
}

/* ====== 程序化砖块绘制工具 ====== */
function drawBrickRow(ctx, s, x, y, w, h, color, seamColor, bevel = true) {
  // 主砖块
  ctx.fillStyle = color
  ctx.fillRect(x, y, w, h)
  // 砖缝（上、左）
  ctx.fillStyle = seamColor
  ctx.fillRect(x, y, w, 1)
  ctx.fillRect(x, y, 1, h)
  if (bevel) {
    // 高光（左上 1px）+ 阴影（右下 1px）模拟立体
    ctx.fillStyle = 'rgba(255,255,255,0.18)'
    ctx.fillRect(x + 1, y + 1, w - 2, 1)
    ctx.fillStyle = 'rgba(0,0,0,0.22)'
    ctx.fillRect(x + 1, y + h - 2, w - 2, 1)
    ctx.fillRect(x + w - 2, y + 1, 1, h - 2)
  }
}

/* 标砖纹（七砖 = 7 块砖/列，标准 240×52 砖 + 1cm 缝）*/
function drawBz(ctx, s, sample) {
  ctx.fillStyle = sample.bg
  ctx.fillRect(0, 0, s, s)
  // 6 列 × 12 行，砖块尺寸用「canvas 边长 ÷ 列(行)数 − 缝」精确推算，
  // 保证 stepX×6 = stepY×12 = s（512）→ 砖块在 canvas 边缘跨边界连续。
  // 原实现用 floor 取整（bw=81/gap=4 步长 85 → 6 列仅 510px；bh=38 步长 42 → 12 行仅 504px），
  // 每 tile 边缘残留 2px / 8px 空隙，重复后与下一 tile 的缝叠加成 2.5~4 倍宽的粗缝
  // —— 这正是用户报告的"中间一条明显粗大砖缝线"。
  const cols = 6, rows = 12, gap = 4
  const stepX = s / cols
  const stepY = s / rows
  const bw = stepX - gap
  const bh = stepY - gap
  for (let row = 0; row < rows; row++) {
    const offset = row % 2 === 0 ? 0 : stepX / 2
    for (let col = -1; col <= cols; col++) {
      const x = col * stepX + offset + gap / 2
      const y = row * stepY + gap / 2
      // 颜色微变化（同色卡多种砖）
      const idx = Math.abs(row * 7 + col * 3) % 5
      const colors = [sample.brick, sample.brick, sample.brick, darken(sample.brick, 0.85), lighten(sample.brick, 1.08)]
      drawBrickRow(ctx, s, x, y, bw, bh, colors[idx], sample.seam)
    }
  }
  addNoise(ctx, s, 8)
}

/* 粗砖纹（厚砖 + 表面凹凸纹理） */
function drawCz(ctx, s, sample) {
  ctx.fillStyle = sample.bg
  ctx.fillRect(0, 0, s, s)
  // 4 行 × 8 列（砖块约 124×124）
  const bw = Math.floor(s / 4) - 6
  const bh = Math.floor(s / 8) - 6
  const gap = 6
  for (let row = 0; row < 8; row++) {
    const offset = row % 2 === 0 ? 0 : bw / 2 + gap / 2
    for (let col = -1; col < 5; col++) {
      const x = col * (bw + gap) + offset
      const y = row * (bh + gap)
      drawBrickRow(ctx, s, x + 3, y + 3, bw - 6, bh - 6, sample.brick, sample.seam, true)
      // 砖面随机点（凹/凸）
      for (let k = 0; k < 12; k++) {
        const px = x + 3 + Math.random() * (bw - 6)
        const py = y + 3 + Math.random() * (bh - 6)
        ctx.fillStyle = Math.random() > 0.5 ? 'rgba(255,255,255,0.22)' : 'rgba(0,0,0,0.18)'
        ctx.fillRect(px, py, 2, 2)
      }
    }
  }
  addNoise(ctx, s, 10)
}

/* 宽窄纹（宽窄交替：两窄 + 一宽 循环） */
function drawKz(ctx, s, sample) {
  ctx.fillStyle = sample.bg
  ctx.fillRect(0, 0, s, s)
  const gap = 4
  // 「窄-窄-宽」为一个周期，3 个周期精确铺满 canvas（cycle = s/3）→ tile 跨边界连续。
  // 原实现列宽 floor 取整（窄 36/宽 69）且行步长 floor（14 行仅 504px），
  // tile 重复时残缝叠加会形成与 BZ-012 同类的粗砖缝。
  const cycle = s / 3
  const wNarrow = (cycle - 3 * gap) / 4
  const wWide = wNarrow * 2
  const pos = [0, wNarrow + gap, 2 * (wNarrow + gap)]
  const rows = 14
  const stepY = s / rows
  const bh = stepY - gap
  for (let row = 0; row < rows; row++) {
    const offset = row % 2 === 0 ? 0 : cycle / 2
    for (let rep = -1; rep <= 3; rep++) {
      for (let c = 0; c < 3; c++) {
        const w = c === 2 ? wWide : wNarrow
        const x = rep * cycle + pos[c] + offset + gap / 2
        const y = row * stepY + gap / 2
        drawBrickRow(ctx, s, x, y, w, bh, sample.brick, sample.seam, false)
      }
    }
  }
  addNoise(ctx, s, 6)
}

/* 平面纹：纯色 + 微弱噪点 + 微微的光泽 */
function drawPm(ctx, s, sample) {
  ctx.fillStyle = sample.hex
  ctx.fillRect(0, 0, s, s)
  // 上下渐变（顶亮底暗）模拟表面光照
  const grad = ctx.createLinearGradient(0, 0, 0, s)
  grad.addColorStop(0, 'rgba(255,255,255,0.06)')
  grad.addColorStop(1, 'rgba(0,0,0,0.08)')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, s, s)
  addNoise(ctx, s, 5)
}

/* ====== 辅助：颜色加深/减淡 ====== */
function darken(hex, k) {
  const c = hex.replace('#', '')
  const r = Math.max(0, Math.min(255, Math.round(parseInt(c.slice(0, 2), 16) * k)))
  const g = Math.max(0, Math.min(255, Math.round(parseInt(c.slice(2, 4), 16) * k)))
  const b = Math.max(0, Math.min(255, Math.round(parseInt(c.slice(4, 6), 16) * k)))
  return `rgb(${r},${g},${b})`
}
function lighten(hex, k) {
  return darken(hex, k) // 同公式（k<1 减淡，k>1 加亮）
}

/* ====== 原有程序化贴图（兼容） ====== */
function drawCorrugated(ctx, s, periods, base, amp) {
  ctx.fillStyle = base
  ctx.fillRect(0, 0, s, s)
  for (let x = 0; x < s; x++) {
    const v = Math.sin((x / s) * Math.PI * 2 * periods)
    const b = Math.round(amp * v)
    ctx.fillStyle = `rgb(${128 + b},${128 + b},${132 + b})`
    ctx.fillRect(x, 0, 1, s)
  }
  addNoise(ctx, s, 6)
}
function drawBrushed(ctx, s) {
  ctx.fillStyle = '#b9bec4'
  ctx.fillRect(0, 0, s, s)
  for (let y = 0; y < s; y++) {
    const b = 178 + Math.round((Math.random() - 0.5) * 46)
    ctx.fillStyle = `rgb(${b},${b + 2},${b + 5})`
    ctx.fillRect(0, y, s, 1)
  }
  addNoise(ctx, s, 4)
}
function drawFlat(ctx, s, hex) {
  ctx.fillStyle = hex
  ctx.fillRect(0, 0, s, s)
  addNoise(ctx, s, 4)
}

export function getWallTexture(id) {
  if (cache.has(id)) return cache.get(id)
  let tex

  // 用户纹理：标砖/粗砖/宽窄/平面
  if (id.startsWith('bz-')) {
    const key = id.slice(3)
    const sample = SAMPLES.bz.find((s) => s.name.startsWith(key))
    if (sample) { tex = canvasTexture((c, s) => drawBz(c, s, sample)); cache.set(id, tex); return tex }
  }
  if (id.startsWith('cz-')) {
    const key = id.slice(3)
    const sample = SAMPLES.cz.find((s) => s.name.startsWith(key))
    if (sample) { tex = canvasTexture((c, s) => drawCz(c, s, sample)); cache.set(id, tex); return tex }
  }
  if (id.startsWith('kz-')) {
    const key = id.slice(3)
    const sample = SAMPLES.kz.find((s) => s.name.startsWith(key))
    if (sample) { tex = canvasTexture((c, s) => drawKz(c, s, sample)); cache.set(id, tex); return tex }
  }
  if (id.startsWith('pm-')) {
    const key = id.slice(3)
    const sample = SAMPLES.pm.find((s) => s.name.startsWith(key))
    if (sample) { tex = canvasTexture((c, s) => drawPm(c, s, sample)); cache.set(id, tex); return tex }
  }

  // 原有程序化贴图
  switch (id) {
    case 'corrugated': tex = canvasTexture((c, s) => drawCorrugated(c, s, 10, '#9aa1a8', 42)); break
    case 'container': tex = canvasTexture((c, s) => drawCorrugated(c, s, 4, '#7d858d', 55)); break
    case 'brushed': tex = canvasTexture(drawBrushed); break
    case 'white': tex = canvasTexture((c, s) => drawFlat(c, s, '#eef0f2')); break
    case 'dark': tex = canvasTexture((c, s) => drawFlat(c, s, '#4a4f54')); break
    default: return null
  }
  cache.set(id, tex)
  return tex
}

// 磨砂玻璃纹理：半透明白底 + 随机细密噪点（配合高粗糙度呈现雾化质感）
let frostedCache = null
export function getFrostedTexture() {
  if (frostedCache) return frostedCache
  const s = 256
  const cv = document.createElement('canvas')
  cv.width = cv.height = s
  const ctx = cv.getContext('2d')
  ctx.clearRect(0, 0, s, s)
  ctx.fillStyle = 'rgba(255,255,255,0.85)'
  ctx.fillRect(0, 0, s, s)
  for (let i = 0; i < 9000; i++) {
    const v = 120 + (Math.random() - 0.5) * 80
    ctx.fillStyle = `rgba(${v},${v},${v + 4},${0.08 + Math.random() * 0.22})`
    const r = 1 + Math.random() * 2.2
    ctx.fillRect(Math.random() * s, Math.random() * s, r, r)
  }
  const tex = new THREE.CanvasTexture(cv)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  frostedCache = tex
  return tex
}