/**
 * editorState.js — 编辑器轻量共享状态（新页面专用，不依赖旧 store）
 */
import { reactive } from 'vue'
import { SCALE } from './catalog'

export const editorState = reactive({
  /** 右侧面板当前 tab：overall(整体设置) | library(部件库) | props(属性) */
  tab: 'overall',
  /** 整体尺寸标注显示开关（3D 视口，默认开启） */
  showDims: true,
  /** 整体设置聚焦字段：'length' | 'width' | 'height'（点击尺寸标注时设置） */
  focusField: '',
  /** 当前选中项：{ section, kind: 'combo'|'part', item, group, part } */
  selected: null,
  /** 3D 视口：部件库点击 → 视角聚焦请求（nonce 递增触发） */
  focus: { key: '', nonce: 0 },
  /** 3D 视口：尺寸编辑请求（key='model' 为整体；nonce 递增触发） */
  sizeEdit: { key: '', size: null, nonce: 0 },
  /** 门窗素材库（sucai.glb）：list = [{ id, name, type: 'door'|'window' }] */
  assets: { list: [], loaded: false },
  /** 各组合体当前替换素材：key（如 W1 / door）→ assetId（如 windowModal3） */
  replacements: {},
  /** 3D 视口：素材替换请求（restore=true 时恢复原始部件；nonce 递增触发） */
  assetEdit: { key: '', assetId: '', restore: false, nonce: 0 },
  /** 墙体贴图：cur = 最近一次应用 { key, texId, density }；uploaded = 已上传纹理列表 */
  textures: {
    cur: { key: '', texId: '', density: 3 },
    uploaded: []
  },
  /** 3D 视口：贴图应用请求（all=true 应用全部墙体；nonce 递增触发） */
  textureEdit: { key: '', texId: '', density: 3, all: false, nonce: 0 },
  /** 3D 视口：纹理上传请求（dataURL 由 FileReader 读取；all=true 应用到全部墙体；nonce 递增触发） */
  uploadTexture: { name: '', dataURL: '', all: true, nonce: 0 },
  /** 3D 视口：位置编辑请求（key='model' 忽略；pos 为世界坐标米；nonce 递增触发） */
  posEdit: { key: '', pos: null, nonce: 0 },
  /** 3D 视口：双击部件 → 请求展开（窄屏底部抽屉）操作面板（nonce 递增触发，RightPanel 监听） */
  panelOpen: { nonce: 0 },
  /** 移动端底部抽屉当前是否展开（RightPanel 维护；Viewer3D 据此自动上移模型视角防遮挡） */
  mobileSheetOpen: false,
  /** 各选中键当前世界中心位置（米）：模型加载后回填、位置编辑后更新 */
  positions: {},
  /** 3D 视口状态 */
  viewport: {
    ready: false,
    loading: false,
    error: ''
  },
  /** 全局显示：分组显隐 + 网格地面 */
  display: {
    groups: { door: true, window: true, roof: true, floor: true, wall: true, frame: true },
    grid: true
  },
  /** 子部件单独显隐：mesh 名（partName）→ false 表示隐藏（组合体子部件） */
  partVisible: {},
  /** 当前选中项显隐：组合体 id / 单部件 id → false 表示隐藏 */
  keyVisible: {},
  /** 玻璃质感：opacity 透明度 / frosted 磨砂 / scope 作用域（'part' 当前部件 | 'all' 全部玻璃门窗） */
  glass: {
    opacity: 0.65,
    frosted: true,
    scope: 'part'
  },
  /**
   * 门窗玻璃独立设置：组合体 key（door / W1~W8）→ { opacity, frosted, color }
   * 未设置（无此 key）→ 该组合体玻璃跟随全局 glass 默认值
   * color 仅窗使用（'#ffffff' 透明无色 / 任意 hex）
   */
  glassPerKey: {},
  /** 各组合体玻璃信息（Viewer3D 回填，UI 据此显示/隐藏玻璃设置项）：key → { main, asset, has } */
  glassInfo: {},
  /** 光照与背景（Viewer3D 实时应用；默认值参考旧版：hemi 0.55 / key 1.7 / fill 0.4） */
  lighting: {
    hemi: 0.55,         // 半球环境光强度（旧版 0.55）
    key: 1.7,           // 平行主光强度（旧版 1.7）
    fill: 0.4,          // 平行补光强度
    dirX: 6, dirY: 9, dirZ: 5, // 主光方向（世界坐标）
    background: '#e9f0f8'      // 场景背景色
  },
  /** 尺寸（米）：model = 整体长宽高（切换模型时由 resetForModel 按该模型 orig 重设）；
   *  parts[key] = 各选中键的实际包围盒尺寸（模型加载后回填） */
  sizes: {
    model: { x: 0, y: 0, z: 0 },
    parts: {}
  },
  /** 门开合：open = true 开门 / false 关门（nonce 递增触发 Viewer3D 播放动画） */
  door: {
    open: false,
    nonce: 0
  },
  /** 窗滑动开合：key = 窗组合体 id（W1~W8）；dir = 'left'（右扇向左滑）| 'right'（左扇向右滑）| ''（关闭）（nonce 递增触发） */
  windowSlide: {
    key: '',
    dir: '',
    nonce: 0
  },
  /** 门推拉开合：key = 门组合体 id（模型 22 的 door1 = X- 端大玻璃推拉门）；dir = 'left'（右扇向左滑）| 'right'（左扇向右滑）| ''（关闭）（nonce 递增触发） */
  doorSlide: {
    key: '',
    dir: '',
    nonce: 0
  },
  /** 法式门平开（模型 22 的门1/2/3：左右双扇绕各自外侧竖铰链朝 +Z 外平开 ~90°）。key = 门组合体 id；open = true 开 / false 关（nonce 递增触发） */
  frenchDoor: {
    key: '',
    open: false,
    nonce: 0
  },
  /** 素材窗平开（窗素材 01：左右窗扇绕外侧竖铰链向外开）：key = 窗组合体 id；open = true 开 / false 关（nonce 递增触发） */
  windowOpen: {
    key: '',
    open: false,
    nonce: 0
  },
  /**
   * 门窗组合体当前实际包含的子部件（素材替换后由 Viewer3D 回填）。
   * key（door / W1~W8）→ { assetId, parts: [{ id(显隐 token, 形如 'W1|glass'), name(显示名), material(材质名) }] }
   * 无该 key = 未替换 → 面板「包含子部件」展示 catalog 原始部件列表
   */
  assetChildren: {}
})

/**
 * 选中组合体。
 * @param {boolean} switchTab 是否同时切到属性面板（双击 true / 单击 false）
 */
export function selectItem(section, item, switchTab = true) {
  editorState.selected = { section, kind: 'combo', item }
  if (switchTab) editorState.tab = 'props'
}

/**
 * 选中单部件（墙体 / 框架 / 组合体子件）。
 * @param {boolean} switchTab 是否同时切到属性面板
 */
export function selectPart(section, group, part, switchTab = true) {
  editorState.selected = { section, kind: 'part', group, part }
  if (switchTab) editorState.tab = 'props'
}

/** 请求 3D 视口把相机飞向某个选中键（组合体 id 或编号部件 id） */
export function requestFocus(key) {
  if (!key) return
  editorState.focus.key = key
  editorState.focus.nonce++
}

/** 请求 3D 视口应用尺寸（key='model' 为整体缩放；否则为该选中键的包围盒目标尺寸） */
export function requestSizeEdit(key, size) {
  if (!key || !size) return
  editorState.sizeEdit.key = key
  editorState.sizeEdit.size = { x: +size.x, y: +size.y, z: +size.z }
  editorState.sizeEdit.nonce++
}

export function clearSelection() {
  editorState.selected = null
}

/** 请求 3D 视口把某组合体替换为素材（key = 窗/门组合体 id，assetId = doorModalN / windowModalN） */
export function requestAssetReplace(key, assetId) {
  if (!key || !assetId) return
  editorState.assetEdit.key = key
  editorState.assetEdit.assetId = assetId
  editorState.assetEdit.restore = false
  editorState.assetEdit.nonce++
}

/** 请求 3D 视口恢复某组合体的原始部件 */
export function requestAssetRestore(key) {
  if (!key) return
  editorState.assetEdit.key = key
  editorState.assetEdit.restore = true
  editorState.assetEdit.nonce++
}

/**
 * 请求 3D 视口应用墙体贴图。
 * @param {string} key 单部件 id（wall_01 等）；all=true 时忽略
 * @param {string} texId 纹理 id（'original' 恢复原始贴图；'bz-...'/'cz-...' 等内置；'up-...' 已上传）
 * @param {number} density 贴图重复密度
 * @param {boolean} all 是否应用到全部墙体
 */
export function requestTextureApply(key, texId, density, all = false) {
  if (!texId) return
  editorState.textureEdit.key = key || ''
  editorState.textureEdit.texId = texId
  editorState.textureEdit.density = density || 3
  editorState.textureEdit.all = !!all
  editorState.textureEdit.nonce++
}

/** 请求 3D 视口把上传的图片加入纹理库（成功后自动应用到墙体）
 *  @param {boolean} all 是否应用到全部墙体（2026-09-16 起默认 true，与面板勾选框一致） */
export function requestTextureUpload(name, dataURL, all = true) {
  if (!dataURL) return
  editorState.uploadTexture.name = name || '上传纹理'
  editorState.uploadTexture.dataURL = dataURL
  editorState.uploadTexture.all = !!all
  editorState.uploadTexture.nonce++
}

/**
 * 请求 3D 视口把选中部件移动到指定世界坐标（中心点，米）。
 * @param {string} key 组合体 id 或编号部件 id（wall_01 / W1 / door / MeshN）
 * @param {{x:number,y:number,z:number}} pos 目标世界中心坐标
 */
export function requestPositionEdit(key, pos) {
  if (!key || !pos) return
  editorState.posEdit.key = key
  editorState.posEdit.pos = { x: +pos.x, y: +pos.y, z: +pos.z }
  editorState.posEdit.nonce++
}

/** 请求 3D 视口开门 / 关门（门开合动画 + 相机进入/退出室内） */
export function requestDoorToggle(open) {
  editorState.door.open = !!open
  editorState.door.nonce++
}

/** 请求 3D 视口窗户滑动开合：dir = 'left'（右扇向左滑至与左扇重合）| 'right'（左扇向右滑至与右扇重合）| ''（关闭复位） */
export function requestWindowSlide(key, dir) {
  if (!key) return
  editorState.windowSlide.key = key
  editorState.windowSlide.dir = dir || ''
  editorState.windowSlide.nonce++
}

/** 请求 3D 视口门平开 / 关闭（仅「双扇平开门」组合体生效，如模型 22 的 door1）：dir='open' 开，'' 关 */
export function requestDoorSlide(key, dir) {
  if (!key) return
  editorState.doorSlide.key = key
  editorState.doorSlide.dir = dir || ''
  editorState.doorSlide.nonce++
}

/**
 * 请求 3D 视口法式门平开 / 关闭（仅「法式门」组合体生效，如模型 22 的门1/2/3）：
 * 左右双扇绕各自外侧竖铰链朝门外侧方向各旋转 90°。
 * @param {string} key 门组合体 id（door1 / door2 / door3）
 * @param {boolean} open true 开 / false 关
 */
export function requestFrenchDoor(key, open) {
  if (!key) return
  editorState.frenchDoor.key = key
  editorState.frenchDoor.open = !!open
  editorState.frenchDoor.nonce++
}

/** 请求 3D 视口素材窗外向平开 / 关闭（窗素材替换后生效：左右窗扇绕外侧铰链向外开） */
export function requestWindowOpen(key, open) {
  if (!key) return
  editorState.windowOpen.key = key
  editorState.windowOpen.open = !!open
  editorState.windowOpen.nonce++
}

/**
 * 切换主模型前重置全部与"当前模型"绑定的状态（key 级字典会被新模型 backfill 重建，
 * 避免旧模型残留 key 串入新模型）。ctx 来自 modelCtx.getCtx()（含 MODEL_ORIG）。
 */
export function resetForModel(ctx) {
  const orig = ctx.MODEL_ORIG || { x: 1, y: 1, z: 1 }
  // 若 meta 声明 orig 已是真实米数（origInMeters=true），则不再额外乘 SCALE。
  const scale = ctx.meta && ctx.meta.origInMeters ? 1 : SCALE
  editorState.selected = null
  editorState.tab = 'overall' // 默认显示整体设置（2026-09-11 用户要求；原为 library）
  editorState.sizes.model = {
    x: +(orig.x * scale).toFixed(3),
    y: +(orig.y * scale).toFixed(3),
    z: +(orig.z * scale).toFixed(3)
  }
  editorState.sizes.parts = {}
  editorState.positions = {}
  editorState.keyVisible = {}
  editorState.partVisible = {}
  editorState.glassPerKey = {}
  editorState.glassInfo = {}
  editorState.replacement = {}
  editorState.replacements = {}
  editorState.assetChildren = {}
  // ⚠ 这里**不要**重置 `editorState.assets`：它是**素材目录**（sucai.fbx 解析出的可选门窗清单），
  //   与具体模型无关（门窗素材 sucai.fbx 全局共用），属于「全局只加载一次」的只读基础数据。
  //   而上面两行 `replacements` / `assetChildren` 是**逐模型的替换结果**，必须清掉。
  //   历史坑：曾在此处把 assets 一起清空 → 若素材库已先解析完，目录会被静默抹掉，
  //   右面板永久停在「素材库加载中…」、视口右键浮层显示「素材库未加载」。
  //   Viewer3D 侧另有 `publishAssetLibrary()` 幂等兜底（模型加载完成后会再发布一次）。
  editorState.textures.cur = { key: '', texId: '', density: 3 }
  editorState.display.groups = { door: true, window: true, roof: true, floor: true, wall: true, frame: true }
  editorState.door.open = false
  editorState.windowSlide = { key: '', dir: '', nonce: 0 }
  editorState.doorSlide = { key: '', dir: '', nonce: 0 }
  editorState.frenchDoor = { key: '', open: false, nonce: 0 }
  editorState.windowOpen = { key: '', open: false, nonce: 0 }
  editorState.mobileSheetOpen = false
  editorState.viewport.ready = false
  editorState.viewport.loading = false
  editorState.viewport.error = ''
  // 让正在等待的跨组件指令失效
  editorState.focus.nonce++
  editorState.sizeEdit.nonce++
  editorState.assetEdit.nonce++
  editorState.posEdit.nonce++
  editorState.door.nonce++
}
